near(byId('add-kg').compute({dis:10000,kg:6,load:500,loadkg:12}).value,(60000+6000)/10500,'KG loading arithmetic');
near(byId('corrected-gm').compute({km:9.1,kg:7.5,fsc:0.3}).value,1.3,'GM correction arithmetic');
near(byId('tpc').compute({aw:2000,rho:1.025}).value,20.5,'TPC example');
near(byId('trim-change').compute({weight:100,distance:30,mct:250}).value,12,'trim example');
near(byId('three-phase').compute({u:440,i:120,pf:0.85}).value,Math.sqrt(3)*440*120*0.85/1000,'three-phase power example');
near(byId('voyage-fuel').compute({dist:1200,speed:12,daily:24}).value,100,'voyage fuel known example');
near(byId('battery-runtime').compute({cap:800,dod:.8,eta:.9,load:96}).value,6,'battery autonomy example');
near(byId('parallel-resistance').compute({r1:100,r2:100}).value,50,'parallel resistor example');
ok(byId('discharge-kg').compute({dis:100,kg:5,removed:100,remkg:4}).invalid!==null,'invalid mass removal rejected');
for(const e of exercises)ok(Number.isFinite(e.expected)&&e.unit&&e.steps.length>0,'exercise integrity: '+e.id);
near(byId('molar-concentration').compute({moles:2,litres:0.5}).value,4,'molar concentration');
near(byId('ph').compute({activity:0.001}).value,3,'pH from ion activity');
near(byId('amp-feedback').compute({gain:100,beta:0.02}).value,100/3,'negative-feedback gain');
near(byId('db-gain').compute({vin:0.1,vout:1}).value,20,'voltage gain dB');
near(byId('buck-converter').compute({vin:48,duty:0.25}).value,12,'buck DC/DC');
near(byId('otto-efficiency').compute({ratio:8,kappa:1.4}).value,100*(1-1/Math.pow(8,0.4)),'ideal Otto cycle');
near(byId('refrigeration-cop').compute({h1:400,h2:440,h4:240}).value,4,'refrigeration COP');
near(byId('real-interest').compute({nominal:6,inflation:2}).value,100*((1.06/1.02)-1),'real interest');
near(byId('shaft-torsion-stress').compute({torque:200,diameter:50}).value,16*200000/(Math.PI*125000),'solid shaft torsion');
near(byId('annuity-pv').compute({payment:1000,r:0,periods:5}).value,5000,'annuity zero-rate edge');
ok(byId('refrigeration-cop').compute({h1:400,h2:400,h4:240}).invalid!==null,'zero compressor work rejected');
ok(byId('otto-efficiency').compute({ratio:1,kappa:1.4}).invalid!==null,'invalid engine compression ratio rejected');
near(byId('sound-db').compute({out:100,input:10}).value,10,'sound power ratio is 10 dB');
near(byId('rc-filter').compute({r:10,c:1}).value,1/(2*Math.PI*.01),'RC cutoff for 10 kΩ and 1µF');
near(byId('fullwave-rectifier').compute({rms:24}).value,2*Math.SQRT2*24/Math.PI,'full-wave rectifier with RMS-to-peak');
near(byId('engine-displacement').compute({bore:100,stroke:100,cyl:4}).value,Math.PI,'engine displacement four cylinders in litres');
near(byId('mean-piston-speed').compute({stroke:0.5,rpm:600}).value,10,'mean piston speed');
near(byId('steam-boiler-heat').compute({flow:3600,hout:2500,hin:500}).value,2000,'steam heat duty with kg/h to kg/s');
near(byId('cooling-cop').compute({h1:400,h2:450,h4:250}).value,3,'cooling COP from enthalpies');
near(byId('shaft-torsion').compute({d:10}).value,Math.PI*1e4/32,'polar shaft second moment');
near(byId('annuity-payment').compute({pv:100000,rate:0,periods:10}).value,10000,'annuity with zero interest');
near(byId('npv').compute({cost:100,flow:55,rate:0,years:2}).value,10,'NPV zero rate');
near(byId('wave-speed').compute({freq:50,lambda:6}).value,300,'wave speed');
near(byId('sound-level').compute({p:0.02,p0:0.00002}).value,60,'acoustic pressure level');
ok(byId('cooling-cop').compute({h1:400,h2:400,h4:250}).invalid!==null,'nonpositive compressor work rejected');
ok(byId('wet-steam-enthalpy').compute({hf:2750,hg:670,x:0.5}).invalid!==null,'invalid wet steam saturation ordering rejected');
const ids=[...html.matchAll(/\sid="([^"]+)"/g)].map(m=>m[1]);
ok(new Set(ids).size===ids.length,'HTML IDs unique');
const appIds=[...srcApp.matchAll(/el\("([^"]+)"\)/g)].map(m=>m[1]);
ok(appIds.every(id=>ids.includes(id)),'all application DOM IDs exist');
ok(html.includes('formulas.js')&&html.includes('formulas-extension.js')&&html.includes('calculators.js')&&html.includes('calculators-extension.js')&&html.includes('formulas-expansion-v1.js')&&html.includes('calculators-expansion-v1.js')&&html.includes('app.js')&&html.includes('styles.css'),'all student assets loaded');
ok(html.includes('noindex,nofollow'),'development student page not indexable yet');
ok(!srcApp.includes('fetch(')&&!srcApp.includes('sendBeacon'),'learning workspace makes no API or analytics calls');
ok(css.includes('@media(max-width:680px)')&&css.includes('@media print'),'responsive and printable styles exist');
ok(css.includes('[data-theme="bridge"]'),'Bridge Dark theme exists');
ok(main.includes('href="/students/"')&&education.includes('href="../students/"'),'student entrypoints linked in main/education');
ok(sw.includes("'./students/'")&&sw.includes("'./students/formulas-extension.js'")&&sw.includes("'./students/calculators-extension.js'")&&sw.includes("'./students/formulas-expansion-v1.js'")&&sw.includes("'./students/calculators-expansion-v1.js'")&&sw.includes("'./students/app.js'"),'student assets precached for PWA offline');
ok(html.includes('www.nb.no/items/7dd9087d6a49416798fe7b2f6fdd86c2'),'Gyldendal/NB title linked as original source');
ok(html.includes('<html lang="en"'),'student page language is English');
ok(!html.includes('id="student-lang"')&&!srcApp.includes('student-lang'),'language selector and switching removed');
ok(!srcApp.includes('state.lang')&&!srcApp.includes('tr.no'),'English-only script without stale language state');
ok(!html.includes("Not a substitute for a vessel's approved loading software"),'requested calculator notice removed');
ok(!html.includes('EDUCATIONAL USE ONLY')&&!html.includes('Kun til utdanning'),'requested generic safety section removed');
ok(!css.includes('.safety{')&&!css.includes('.result-foot{'),'unused generic-warning styles removed');

const study=sandbox.MT_STUDY;
ok(study.groups.length===8,'eight cross-discipline groups defined');
ok(study.groups.flatMap(g=>g.categories).length===28,'28 subject categories mapped to study groups');
ok(new Set(study.groups.flatMap(g=>g.categories)).size===28,'study subject grouping unambiguous');
ok(formulas.every(f=>study.groups.some(g=>g.categories.includes(f.category))),'all 366 formula entries have a study discipline');
ok(Object.keys(study.calculatorByFormula).length>=50,'at least fifty explicit formula-to-calculator mappings');
ok(Object.entries(study.calculatorByFormula).every(([id,cid])=>formulas.some(f=>f.id===id)&&calculators.some(c=>c.id===cid)),'all explicit formula-to-calculator IDs valid');
ok(Object.keys(study.details).length>=20,'curated symbol definitions for core formulas');
ok(Object.entries(study.details).every(([id,d])=>formulas.some(f=>f.id===id)&&Array.isArray(d.symbols)&&d.symbols.every(v=>v.symbol&&v.meaning&&v.unit)),'curated formula symbols have units and meanings');
ok(Object.keys(study.figures).length===5,'five original SVG learning diagrams');
ok(Object.values(study.figures).every(fig=>fig.includes('<svg')&&fig.includes('role="img"')&&fig.includes('aria-label')),'SVG diagrams accessible via descriptive labels');
ok(formulas.every(f=>Boolean(study.topicChapters[f.category])),'all formula categories have topical source mapping');
ok(study.chapterLabel.includes('not evidence'),'topic mapping clearly marked unverified at equation level');
ok(html.includes('id="study-group"')&&html.includes('id="practice-subject"')&&html.includes('id="practice-difficulty"'),'subject and difficulty controls present');
ok(html.includes('id="show-hint"')&&html.includes('id="exercise-hint"'),'hint view present');
ok(html.includes('id="sheet-formulas"')&&html.includes('id="print-sheet"'),'saved formula sheet and export control present');
ok(html.includes('learning-data.js')&&sw.includes("'./students/learning-data.js'"),'study data loaded and cached offline');
ok(srcApp.includes('study.calculatorByFormula[f.id]')&&!srcApp.includes('calc.find(c=>c.category===f.category'),'only exact formula-to-calculator links used');
ok(srcApp.includes('if(!state.attempted)return')&&srcApp.includes('state.attempted=true'),'worked solution locked until answer attempt');
ok(srcApp.includes('mt-student-formulas-fav-v1')&&srcApp.includes('print-sheet'),'saved selections drive printable sheet');
ok(css.includes('body.print-sheet .sheet-formulas')&&css.includes('.symbol-grid'),'print stylesheet and symbol legend styles present');
ok(!srcApp.includes('fetch(')&&!srcApp.includes('sendBeacon'),'student resources remain local-only');

const symbolIndex=sandbox.MT_SYMBOLS;
ok(symbolIndex.entries.length>=65,'symbol register contains curated contextual entries');
ok(symbolIndex.coverage.formulas===formulas.length,'symbol register indexes entire formula catalogue without claiming completeness');
ok(symbolIndex.find('Q').filter(v=>v.symbol==='Q').some(v=>v.meaning.includes('Electric charge')),'Q electric charge is represented');
ok(symbolIndex.find('Q').filter(v=>v.symbol==='Q').some(v=>v.meaning.includes('flow')),'Q volume flow is distinct from charge');
ok(symbolIndex.find('Q').filter(v=>v.symbol==='Q').some(v=>v.meaning.includes('heat')),'Q heat is distinct from charge and flow');
ok(symbolIndex.find('P').some(v=>v.meaning==='Proportional band'),'P proportional band remains independently interpreted');
ok(symbolIndex.entries.every(v=>v.symbol&&v.meaning&&v.unit&&v.quantityId&&v.status),'symbol entries contain subject-scoped meaning, unit, identity and review status');
ok(symbolIndex.entries.filter(v=>v.formulaId).every(v=>formulas.some(f=>f.id===v.formulaId)),'all linked symbols resolve to existing formula IDs');
ok(html.includes('src="symbol-index.js?v=students-draft-6"')&&sw.includes("'./students/symbol-index.js'"),'symbol metadata loads and is available offline');
ok((html.match(/src="learning-data.js/g)||[]).length===1,'curriculum loader is not duplicated');
ok(html.includes('data-tab="symbols"')&&html.includes('id="symbol-search"'),'context-aware symbol lookup tab and search exist');

ok(formulas.length>=372,'photo-review expansion retains original photographed formulas');
ok(Object.keys(sandbox.MT_STUDY.photoReview).length>=72,'context symbol tables cover photographed pages and reviewed mathematics contexts');
ok(Object.keys(sandbox.MT_STUDY.details).length>=90,'at least 32 curated contextual formula guides');
ok(['79','150','197'].every(n=>Object.values(sandbox.MT_STUDY.photoReview).some(x=>String(x.page)===n)),'all three photographed printed pages represented');
ok(html.includes('book-photos-20261020.js')&&sw.includes("'./students/book-photos-20261020.js'"),'photo metadata loads and caches');
ok(formulas.some(f=>f.id==='photo-20261020-multistream-boiler-efficiency'),'five-stream boiler balance included');
ok(!formulas.some(f=>f.id==='bookphoto-20261020-density-displacement'),'ambiguous density correction excluded until physical review');
const mathAudit=sandbox.MT_STUDY.mathChapter20261020;
ok(mathAudit.sourcePrintedPages[0]===7&&mathAudit.sourcePrintedPages[1]===22,'mathematics chapter photo range confirmed 7–22');
ok(mathAudit.reviewedFormulaIds.length===59,'59 existing and new mathematics formula contexts annotated');
ok(formulas.length===409,'409 independently written formula catalogue entries loaded');
ok(html.includes('math-chapter-20261020.js')&&sw.includes("'./students/math-chapter-20261020.js'"),'mathematics chapter referenced and offline precached');
ok(formulas.some(f=>f.name==='Spherical sine law'&&f.category==='Geometry & Trigonometry'),'spherical sine law available with domain limits');
ok(formulas.some(f=>f.name==='Probability of union'),'union probability formula included');
ok(formulas.some(f=>f.name==='Derivative product rule'),'derivative product rule included');
ok(sandbox.MT_SYMBOLS.entries.length>=180,'symbol index regenerated for mathematics formula contexts');
ok(sandbox.MT_STUDY.details[formulas.find(f=>f.name==='Sample variance').id].symbols.length>=4,'statistical notation has formula-specific explanations');
console.log(JSON.stringify({result:'PASS',checks:passed,formulas:formulas.length,calculators:calculators.length,exercises:exercises.length,
 note:'Isolated source smoke only; browser reflow, installed PWA and full editorial accuracy are still pending.'}));
